/// <summary>
/// The data contract for a <c>METitemSizeChangeBusinessEvent</c>.
/// </summary>
[DataContract]
public final class METItemPackChangeBusinessEventContract extends BusinessEventsContract
{
    private LegalEntityDataAreaId legalEntity;
    private ItemId itemId;
    private METItemSize itemSize;
    private InventSiteId  inventSiteId;
    private METInventTable  metInventTable;

}

Method.Source:
/// <summary>
///     Constructs a <c>METItemPackChangeBusinessEventContract</c>.
/// </summary>
/// <returns>An instance of <c>METItemPackChangeBusinessEventContract</c>.</returns>
public static METItemPackChangeBusinessEventContract newFromMetItemSiteSettingsSetup(MetItemSiteSettingsSetup  _metItemSiteSettingsSetup)
{
    METItemPackChangeBusinessEventContract contract = new METItemPackChangeBusinessEventContract();
    contract.initialize(_metItemSiteSettingsSetup);
    return contract;
}

    /// <summary>
    /// Initializes the data members
    /// </summary>
    /// <param name = "_metItemSiteSettingsSetup">the itemSiteSettingsSetup record</param>
    private void initialize(MetItemSiteSettingsSetup  _metItemSiteSettingsSetup)
    {
        legalEntity = curExt();
        itemId = _metItemSiteSettingsSetup.ItemId;

        select firstonly metInventTable
            where metInventTable.ItemId == itemId;

        itemSize = metInventTable.ItemSize;
        inventSiteId = _metItemSiteSettingsSetup.InventSiteId;
    }

    [DataMember('LegalEntity'), BusinessEventsDataMember("@ProcurementAndSourcing:LegalEntity")]
    public LegalEntityDataAreaId parmLegalEntity(LegalEntityDataAreaId _legalEntity = legalEntity)
    {
        legalEntity = _legalEntity;

        return legalEntity;
    }

    [DataMember('ItemId'), BusinessEventsDataMember("@MCR23630")]
    public ItemId parmItemId(ItemId _itemId = itemId)
    {
        itemId = _itemId;

        return itemId;
    }

    [DataMember('ItemSize'), BusinessEventsDataMember("@MET:ItemSize")]
    public METItemSize parmItemSize(METItemSize _itemSize = itemSize)
    {
        itemSize = _itemSize;

        return itemSize;
    }

    [DataMember('SiteId'), BusinessEventsDataMember("@MET:SiteId")]
    public InventSiteId parmInventSiteId(InventSiteId _inventSiteId = inventSiteId)
    {
        inventSiteId = _inventSiteId;

        return inventSiteId;
    }
